//! Unicode character properties for shaping (tables generated by
//! scripts/gen_unicode_props.py) and grapheme clusters as HarfBuzz forms
//! them.

const std = @import("std");
const data = @import("unicode_props_data.zig");

fn inRanges(ranges: []const [2]u21, cp: u21) bool {
    var lo: usize = 0;
    var hi: usize = ranges.len;
    while (lo < hi) {
        const mid = (lo + hi) / 2;
        if (cp < ranges[mid][0]) {
            hi = mid;
        } else if (cp > ranges[mid][1]) {
            lo = mid + 1;
        } else return true;
    }
    return false;
}

/// General_Category Mn, Mc or Me.
pub fn isMark(cp: u21) bool {
    return cp >= 0x300 and inRanges(&data.mark_ranges, cp);
}

/// General_Category Mn.
pub fn isNonspacingMark(cp: u21) bool {
    return cp >= 0x300 and inRanges(&data.nonspacing_mark_ranges, cp);
}

/// General_Category L*.
pub fn isLetter(cp: u21) bool {
    if (cp < 0x80) return (cp | 0x20) >= 'a' and (cp | 0x20) <= 'z';
    return inRanges(&data.letter_ranges, cp);
}

/// General_Category is Cf, Cn, Co, Cs, L* or M* (HarfBuzz's FORMAT ..
/// NON_SPACING_MARK range): the character continues a word.
pub fn isWordChar(cp: u21) bool {
    return !inRanges(&data.non_word_ranges, cp);
}

/// The script a character gives a run, as HarfBuzz's
/// guess_segment_properties reads it: none for Common, Inherited and
/// unassigned characters.
pub const RunScript = enum { none, devanagari, other };

pub fn runScript(cp: u21) RunScript {
    if (!inRanges(&data.strong_script_ranges, cp)) return .none;
    return if (inRanges(&data.devanagari_script_ranges, cp)) .devanagari else .other;
}

pub fn isExtendedPictographic(cp: u21) bool {
    return cp >= 0xA9 and inRanges(&data.ext_pict_ranges, cp);
}

fn isRegionalIndicator(cp: u21) bool {
    return cp >= 0x1F1E6 and cp <= 0x1F1FF;
}

/// The canonical single-step decomposition of `cp`: (first, second), the
/// second 0 for a singleton (U+212B -> U+00C5). Null if it has none.
pub fn decomposeOnce(cp: u21) ?[2]u21 {
    if (cp < 0xC0) return null;
    const table = &data.decompositions;
    var lo: usize = 0;
    var hi: usize = table.len;
    while (lo < hi) {
        const mid = (lo + hi) / 2;
        if (cp < table[mid][0]) {
            hi = mid;
        } else if (cp > table[mid][0]) {
            lo = mid + 1;
        } else return .{ table[mid][1], table[mid][2] };
    }
    return null;
}

/// HarfBuzz's space fallback (hb_unicode_funcs_t::space_t): a space
/// character the font lacks is drawn as its space glyph, this wide. The
/// em fractions are the enum value (an em divided by it).
pub const SpaceFallback = enum(u8) {
    none = 0,
    em = 1,
    em_2 = 2,
    em_3 = 3,
    em_4 = 4,
    em_5 = 5,
    em_6 = 6,
    em_16 = 16,
    four_em_18,
    space,
    figure,
    punctuation,
    narrow,

    pub fn of(cp: u21) SpaceFallback {
        return switch (cp) {
            0x0020, 0x00A0 => .space,
            0x2000, 0x2002 => .em_2,
            0x2001, 0x2003, 0x3000 => .em,
            0x2004 => .em_3,
            0x2005 => .em_4,
            0x2006 => .em_6,
            0x2007 => .figure,
            0x2008 => .punctuation,
            0x2009 => .em_5,
            0x200A => .em_16,
            0x202F => .narrow,
            0x205F => .four_em_18,
            else => .none,
        };
    }
};

/// East_Asian_Width W or F.
pub fn isWide(cp: u21) bool {
    return cp >= 0x1100 and inRanges(&data.wide_ranges, cp);
}

/// Cells a cluster takes on a monospaced grid: its widest code point - 2
/// for East Asian Wide or Fullwidth, 0 for a mark, 1 for anything else -
/// at least 1; a variation selector 16 (emoji presentation) makes it 2.
pub fn cells(cluster: []const u21) u8 {
    var n: u8 = 1;
    for (cluster) |cp| {
        if (cp == 0xFE0F or isWide(cp)) n = 2;
    }
    return n;
}

/// UAX #29 Grapheme_Cluster_Break.
pub const Gcb = enum(u4) { other, cr, lf, control, extend, zwj, regional_indicator, prepend, spacing_mark, l, v, t, lv, lvt };
/// Indic_Conjunct_Break (GB9c).
pub const InCB = enum(u2) { none, linker, consonant, extend };

fn graphemeProps(cp: u21) struct { gcb: Gcb, incb: InCB } {
    const t = &data.grapheme_ranges;
    var lo: usize = 0;
    var hi: usize = t.len;
    while (lo < hi) {
        const mid = (lo + hi) / 2;
        if (cp < t[mid][0]) {
            hi = mid;
        } else if (cp > t[mid][1]) {
            lo = mid + 1;
        } else {
            const v: u8 = @intCast(t[mid][2]);
            return .{ .gcb = @fromBackingInt(@intCast(@as(u4, @truncate(v)))), .incb = @fromBackingInt(@intCast(@as(u2, @truncate(v >> 4)))) };
        }
    }
    return .{ .gcb = .other, .incb = .none };
}

/// The end (exclusive) of the extended grapheme cluster that starts at
/// `start` (UAX #29, Unicode 16: GB3-GB13 with GB9c's Indic conjuncts).
pub fn graphemeEnd(cps: []const u21, start: usize) usize {
    if (start >= cps.len) return start;
    var prev = graphemeProps(cps[start]);
    var ri_run: usize = @intFromBool(prev.gcb == .regional_indicator);
    var pict: enum { none, pict, zwj } = if (isExtendedPictographic(cps[start])) .pict else .none;
    var conjunct: enum { none, consonant, linked } = if (prev.incb == .consonant) .consonant else .none;
    var i = start + 1;
    while (i < cps.len) : (i += 1) {
        const cur = graphemeProps(cps[i]);
        const cur_pict = isExtendedPictographic(cps[i]);
        const join = blk: {
            if (prev.gcb == .cr and cur.gcb == .lf) break :blk true; // GB3
            if (prev.gcb == .cr or prev.gcb == .lf or prev.gcb == .control) break :blk false; // GB4
            if (cur.gcb == .cr or cur.gcb == .lf or cur.gcb == .control) break :blk false; // GB5
            if (prev.gcb == .l and (cur.gcb == .l or cur.gcb == .v or cur.gcb == .lv or cur.gcb == .lvt)) break :blk true; // GB6
            if ((prev.gcb == .lv or prev.gcb == .v) and (cur.gcb == .v or cur.gcb == .t)) break :blk true; // GB7
            if ((prev.gcb == .lvt or prev.gcb == .t) and cur.gcb == .t) break :blk true; // GB8
            if (cur.gcb == .extend or cur.gcb == .zwj) break :blk true; // GB9
            if (cur.gcb == .spacing_mark) break :blk true; // GB9a
            if (prev.gcb == .prepend) break :blk true; // GB9b
            if (conjunct == .linked and cur.incb == .consonant) break :blk true; // GB9c
            if (pict == .zwj and cur_pict) break :blk true; // GB11
            if (prev.gcb == .regional_indicator and cur.gcb == .regional_indicator and ri_run % 2 == 1) break :blk true; // GB12, GB13
            break :blk false; // GB999
        };
        if (!join) break;
        ri_run = if (cur.gcb == .regional_indicator) ri_run + 1 else 0;
        pict = if (cur_pict) .pict else if (pict == .pict and cur.gcb == .extend) .pict else if (pict == .pict and cur.gcb == .zwj) .zwj else .none;
        conjunct = switch (cur.incb) {
            .consonant => .consonant,
            .linker => if (conjunct != .none) .linked else .none,
            .extend => conjunct,
            .none => .none,
        };
        prev = cur;
    }
    return i;
}

/// The byte end of the extended grapheme cluster starting at byte `start`
/// of UTF-8 `text` (invalid bytes are clusters of one byte; a cluster is
/// cut after 32 code points).
pub fn graphemeEndBytes(text: []const u8, start: usize) usize {
    if (start >= text.len) return start;
    var cps: [32]u21 = undefined;
    var ends: [32]usize = undefined;
    var n: usize = 0;
    var i = start;
    while (i < text.len and n < cps.len) {
        const len = std.unicode.utf8ByteSequenceLength(text[i]) catch 1;
        const cp = if (i + len <= text.len) std.unicode.utf8Decode(text[i .. i + len]) catch null else null;
        if (cp == null) {
            if (n == 0) return i + 1;
            break; // the invalid byte starts a cluster of its own
        }
        cps[n] = cp.?;
        i += len;
        ends[n] = i;
        n += 1;
    }
    return ends[graphemeEnd(cps[0..n], 0) - 1];
}

/// Sets `cont[i]` when code point i continues the grapheme of the one
/// before it, by HarfBuzz's rules (hb_set_unicode_props): marks, emoji
/// modifiers, the second of a regional indicator pair, ZWJ and an
/// Extended_Pictographic character after it, the halfwidth katakana
/// voiced marks, and tag characters. `cont` is as long as `cps`.
pub fn markContinuations(cps: []const u21, cont: []bool) void {
    var i: usize = 0;
    while (i < cps.len) : (i += 1) {
        const cp = cps[i];
        cont[i] = isMark(cp);
        if (cp >= 0x1F3FB and cp <= 0x1F3FF) {
            cont[i] = true;
        } else if (i > 0 and isRegionalIndicator(cp)) {
            if (isRegionalIndicator(cps[i - 1]) and !cont[i - 1]) cont[i] = true;
        } else if (cp == 0x200D) {
            cont[i] = true;
            if (i + 1 < cps.len and isExtendedPictographic(cps[i + 1])) {
                i += 1;
                cont[i] = true;
            }
        } else if ((cp >= 0xFF9E and cp <= 0xFF9F) or (cp >= 0xE0020 and cp <= 0xE007F)) {
            cont[i] = true;
        }
    }
}

const testing = std.testing;

test "isMark: nonspacing, spacing and enclosing marks" {
    try testing.expect(isMark(0x0301)); // combining acute (Mn)
    try testing.expect(isMark(0x093F)); // Devanagari vowel sign i (Mc)
    try testing.expect(isMark(0x20DD)); // combining enclosing circle (Me)
    try testing.expect(isMark(0xFE0F)); // variation selector (Mn)
    try testing.expect(!isMark('a'));
    try testing.expect(!isMark(0x0915)); // Devanagari ka
    try testing.expect(!isMark(0x200D)); // ZWJ is Cf
    try testing.expect(isNonspacingMark(0x0902)); // Devanagari anusvara (Mn, ccc 0)
    try testing.expect(!isNonspacingMark(0x093F)); // Mc
}

test "markContinuations follows HarfBuzz's grapheme rules" {
    const cps = [_]u21{ 'e', 0x0301, 0x1F1F8, 0x1F1EA, 0x1F1FA, 0x1F468, 0x200D, 0x1F469, 0x1F44D, 0x1F3FD, 0x0915, 0x093F };
    var cont: [cps.len]bool = undefined;
    markContinuations(&cps, &cont);
    // e acute | SE flag pair, then a lone U | man ZWJ woman | thumbs + tone | ka + i
    try testing.expectEqualSlices(bool, &.{ false, true, false, true, false, false, true, true, false, true, false, true }, &cont);
}

test "decomposeOnce: pairs, singletons, exclusions" {
    try testing.expectEqual([2]u21{ 'e', 0x0301 }, decomposeOnce(0x00E9).?);
    try testing.expectEqual([2]u21{ 0x00C5, 0 }, decomposeOnce(0x212B).?); // Angstrom sign
    try testing.expectEqual([2]u21{ 0x0915, 0x093C }, decomposeOnce(0x0958).?); // qa (excluded from composition)
    try testing.expectEqual([2]u21{ 0x0113, 0x0301 }, decomposeOnce(0x1E17).?); // e macron acute
    try testing.expect(decomposeOnce('a') == null);
    try testing.expect(decomposeOnce(0xAC00) == null); // Hangul is algorithmic
}

test "isLetter, isWordChar" {
    try testing.expect(isLetter('Q') and isLetter(0x0915) and isLetter(0x00E9));
    try testing.expect(!isLetter('5') and !isLetter(' ') and !isLetter(0x093F));
    try testing.expect(isWordChar(0x0915) and isWordChar(0x093F) and isWordChar(0x200D) and isWordChar(0xE000));
    try testing.expect(!isWordChar(' ') and !isWordChar('.') and !isWordChar('5') and !isWordChar(0x0964));
}

test "runScript: Devanagari, other scripts, and characters of none" {
    try testing.expectEqual(RunScript.devanagari, runScript(0x0915));
    try testing.expectEqual(RunScript.devanagari, runScript(0x093F)); // matra
    try testing.expectEqual(RunScript.none, runScript(0x0951)); // stress sign: Inherited
    try testing.expectEqual(RunScript.none, runScript(0x0964)); // danda: Common
    try testing.expectEqual(RunScript.none, runScript('5'));
    try testing.expectEqual(RunScript.other, runScript('a'));
}

test "graphemeEnd passes UCD's GraphemeBreakTest.txt" {
    const a = testing.allocator;
    const text = try std.Io.Dir.cwd().readFileAlloc(testing.io, "test/unicode/GraphemeBreakTest.txt", a, .limited(1 << 20));
    defer a.free(text);
    var cps: std.ArrayListUnmanaged(u21) = .empty;
    defer cps.deinit(a);
    var breaks: std.ArrayListUnmanaged(usize) = .empty;
    defer breaks.deinit(a);
    var checked: usize = 0;
    var failed: usize = 0;
    var lines = std.mem.splitScalar(u8, text, '\n');
    while (lines.next()) |raw| {
        const line = std.mem.trim(u8, raw[0 .. std.mem.indexOfScalar(u8, raw, '#') orelse raw.len], " \t\r");
        if (line.len == 0) continue;
        cps.clearRetainingCapacity();
        breaks.clearRetainingCapacity();
        var tokens = std.mem.tokenizeScalar(u8, line, ' ');
        while (tokens.next()) |tok| {
            if (std.mem.eql(u8, tok, "\u{F7}")) {
                // a boundary before code point cps.len (skip the leading one)
                if (cps.items.len > 0) try breaks.append(a, cps.items.len);
            } else if (std.mem.eql(u8, tok, "\u{D7}")) {} else {
                try cps.append(a, try std.fmt.parseInt(u21, tok, 16));
            }
        }
        checked += 1;
        var got: std.ArrayListUnmanaged(usize) = .empty;
        defer got.deinit(a);
        var i: usize = 0;
        while (i < cps.items.len) {
            i = graphemeEnd(cps.items, i);
            try got.append(a, i);
        }
        if (!std.mem.eql(usize, breaks.items, got.items)) {
            failed += 1;
            if (failed <= 5) std.debug.print("\n{s}\n  expected {any}\n  got      {any}\n", .{ line, breaks.items, got.items });
        }
    }
    try testing.expect(checked > 500);
    try testing.expectEqual(@as(usize, 0), failed);
}

test "cells: wide, narrow, marks, emoji presentation" {
    try testing.expectEqual(@as(u8, 2), cells(&.{0xD55C})); // Hangul syllable
    try testing.expectEqual(@as(u8, 2), cells(&.{0x30A2})); // katakana
    try testing.expectEqual(@as(u8, 2), cells(&.{0x6771})); // CJK
    try testing.expectEqual(@as(u8, 1), cells(&.{ 0x0430, 0x0301 })); // a + acute
    try testing.expectEqual(@as(u8, 1), cells(&.{ 0x0915, 0x094D, 0x0937 })); // ksha
    try testing.expectEqual(@as(u8, 1), cells(&.{0x263A})); // smiley, text style
    try testing.expectEqual(@as(u8, 2), cells(&.{ 0x263A, 0xFE0F })); // ... with VS16
    try testing.expectEqual(@as(u8, 2), cells(&.{0x1F600})); // emoji (W)
    try testing.expectEqual(@as(u8, 1), cells(&.{0x0301})); // a lone mark: at least 1
}

test "graphemeEndBytes steps over whole clusters" {
    const text = "e\u{301}xस्ते\u{1F1F8}\u{1F1EA}!";
    var ends: [8]usize = undefined;
    var n: usize = 0;
    var i: usize = 0;
    while (i < text.len) : (n += 1) {
        i = graphemeEndBytes(text, i);
        ends[n] = i;
    }
    try testing.expectEqualSlices(usize, &.{ 3, 4, 16, 24, 25 }, ends[0..n]);
    try testing.expectEqual(@as(usize, 1), graphemeEndBytes("\xffa", 0));
    try testing.expectEqual(@as(usize, 1), graphemeEndBytes("a\xff", 0));
}
